// Hyperbolic Bloom: a tiling of the hyperbolic plane in the Poincare disk,
// like Escher's Circle Limit prints. Regular polygons, several meeting at
// every corner, fit infinitely often and shrink towards the rim. The camera
// glides through that curved space (a Mobius transformation), so tiles
// stream out of the rim, swell, and vanish into it again. Outside the disk
// the same world is mirrored. Rings of light run through every tile and
// surge on the beat; Morph slides them from the tile centres to the corners.

#define TAU 6.28318531
#define PI 3.14159265

mat2 rot(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat2(c, -s, s, c);
}

vec3 palette(float t) {
  return 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.67)));
}

vec2 cmul(vec2 a, vec2 b) {
  return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);
}

vec2 cdiv(vec2 a, vec2 b) {
  return vec2(a.x * b.x + a.y * b.y, a.y * b.x - a.x * b.y) / dot(b, b);
}

vec3 shader(vec2 uv, float time) {
  float j = drift + kick;
  vec2 z = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0) * 2.0;
  float px = 2.0 / resolution.y;

  // Lens: the disk fits the screen, or grows until we are inside it.
  float size = mix(0.94, 3.2, lens * lens);
  z /= size;
  px /= size;
  float r2 = dot(z, z);
  float outside = step(1.0, r2);
  if (r2 > 1.0) {
    // Mirror world: invert the outside into the disk.
    z /= r2;
    px /= r2;
    r2 = 1.0 / r2;
  }
  // How much hyperbolic space one pixel covers grows towards the rim.
  float conf = max(1.0 - r2, 1e-4);

  // Glide: a hyperbolic translation to a wandering point, plus a slow turn.
  float ga = j * 0.05;
  vec2 a = 0.9 * sin(j * 0.13) * vec2(cos(ga), sin(ga));
  vec2 w = cdiv(z - a, vec2(1.0, 0.0) - cmul(vec2(a.x, -a.y), z));
  w = rot(j * 0.017) * w;

  // {P, Q}: P-sided tiles, Q at every corner. Q is raised where needed so
  // the tiling stays hyperbolic (1/P + 1/Q < 1/2).
  float P = float(sides);
  float Q = max(float(meet), floor(2.0 * P / (P - 2.0)) + 1.0);
  float al = PI / P;
  float sa = sin(al);
  float ca = cos(al);
  float cq = cos(PI / Q);
  // The tile edge is a circle that meets the rim at right angles.
  float rr = sa * sa / (cq * cq - sa * sa);
  float rad = sqrt(rr);
  float cc = sqrt(1.0 + rr);
  vec2 C = vec2(cc, 0.0);

  // Fold the point into the fundamental triangle by mirroring it across
  // the tile's symmetry axes and its edge until it stays put.
  float n = 0.0;
  float par = 0.0;
  for (int i = 0; i < 40; i++) {
    float ang = atan(w.y, w.x);
    par += floor(ang / al);
    ang = al - abs(mod(ang, 2.0 * al) - al);
    w = length(w) * vec2(cos(ang), sin(ang));
    vec2 v = w - C;
    float d2 = dot(v, v);
    if (d2 >= rr) break;
    w = C + v * rr / d2;
    n += 1.0;
  }
  par = mod(par + n, 2.0);

  // Size of a pixel in the folded space (the fold preserves hyperbolic
  // distances), for lines that stay crisp at every depth.
  float ps = px * (1.0 - dot(w, w)) / conf;

  float inr = cc - rad;
  float tv = cc * ca - sqrt(max(cc * cc * ca * ca - 1.0, 0.0));
  vec2 V = tv * vec2(ca, sa);
  float e = (length(w - C) - rad) / inr; // 1 at the tile centre, 0 on edges
  float dv = length(w - V) / tv;         // 1 at the tile centre, 0 at corners

  // Near the middle, the journey swings the morph by itself.
  float m = clamp(morph + (0.5 - abs(morph - 0.5)) * 0.8 * sin(j * 0.043), 0.0, 1.0);
  float v = mix(e, dv, m);
  float count = mix(2.0, 9.0, rings);
  float s = v * count + j * 0.22;
  float aw = ps * count / min(inr, tv);
  float detail = 1.0 - smoothstep(0.2, 0.6, aw);

  float hue = colour + j * 0.013 + 0.5 * outside;
  float b = fract(s);
  float tube = sin(PI * b);
  // Keep the dark seams between rings at least a pixel wide.
  tube = smoothstep(0.0, clamp(aw * 3.0, 0.02, 1.0) + 0.35, tube);
  vec3 base = palette(hue + floor(s) * 0.13 + n * 0.07 * (1.0 - m));
  // Each ring is a terrace: lit along its outer lip, shaded where the
  // next one overhangs it.
  vec3 col = base * (0.04 + 0.96 * tube) * (0.45 + 0.75 * b * b);
  col += palette(hue + floor(s) * 0.13 + 0.12) * 0.5 * pow(b, 6.0) * tube;
  // Alternate triangles sit slightly in shadow: a pinwheel in every tile.
  col *= 0.72 + 0.28 * par;

  // Tile edges glow.
  float el = e * inr;
  vec3 edgeCol = palette(hue + 0.5 + n * 0.07);
  float lw = 0.004 + 0.012 * (1.0 - m);
  col = mix(col, edgeCol + 0.35, smoothstep(lw + ps, lw - ps, el) * (1.0 - 0.6 * m));
  col += edgeCol * 0.35 * exp(-el / 0.03) * (1.0 - m);

  // Towards the rim the tiles get smaller than a pixel: dissolve to light.
  vec3 rim = palette(hue + 0.62) * 0.3;
  col = mix(rim, col, detail);
  col += (palette(hue + 0.3) + 0.3) * 0.8 * exp(-conf * 22.0);
  col *= mix(1.0, 0.7, outside);

  return clamp(col, 0.0, 1.0);
}
